// build-complete-app.js
// One-click installer for the College Resource Hub.
// HOW TO USE: save this file in your College-Resource-Hub ROOT folder (the one that contains
// "backend" and "frontend"), then run:   node build-complete-app.js
//
// - Your existing files are BACKED UP first into a folder called "_backup_before_install".
// - Your backend/.env file is never touched.
// - Afterwards run:  cd backend  ->  npm install  ->  npm start

const fs = require("fs");
const path = require("path");

// Every file, stored as base64 text so special characters can never break this script.
const FILES = {
  "backend/.env.example": "",
  "backend/middleware/auth.js": "",
  "backend/models/Announcement.js": "",
  "backend/models/Assignment.js": "",
  "backend/models/Bookmark.js": "",
  "backend/models/CalendarEvent.js": "",
  "backend/models/Report.js": "",
  "backend/models/Resource.js": "",
  "backend/models/Subject.js": "",
  "backend/models/User.js": "",
  "backend/package.json": "",
  "backend/server.js": "",
  "frontend/admin-dashboard.html": "",
  "frontend/announcements.html": "",
  "frontend/assignments.html": "",
  "frontend/bookmarks.html": "",
  "frontend/calendar.html": "",
  "frontend/css/style.css": "",
  "frontend/dashboard.html": "",
  "frontend/index.html": "",
  "frontend/js/script.js": "",
  "frontend/login.html": "",
  "frontend/resources.html": "",
};

const root = __dirname;
const backupRoot = path.join(root, "_backup_before_install");
let written = 0, backedUp = 0;

for (const relPath of Object.keys(FILES)) {
  const target = path.join(root, relPath);
  fs.mkdirSync(path.dirname(target), { recursive: true });

  if (fs.existsSync(target)) {
    const backupPath = path.join(backupRoot, relPath);
    if (!fs.existsSync(backupPath)) {
      fs.mkdirSync(path.dirname(backupPath), { recursive: true });
      fs.copyFileSync(target, backupPath);
      backedUp++;
    }
  }

  fs.writeFileSync(target, Buffer.from(FILES[relPath], "base64"));
  written++;
}

console.log("Done! " + written + " files written, " + backedUp + " old files backed up.");
console.log("");
console.log("NEXT STEPS:");
console.log("  1. cd backend");
console.log("  2. npm install");
console.log("  3. make sure backend/.env has MONGO_URI (see backend/.env.example)");
console.log("     optional: set ADMIN_SIGNUP_CODE too, or the default admin-signup-2026 will be used");
console.log("  4. npm start");
console.log("  5. open http://localhost:3000 in your browser");
